	@Test
	void compactRowsDoNotDispatchThroughGenericObjectMapper() throws Exception {
		String resource = "/org/eclipse/rdf4j/workbench/util/WorkbenchPageResultWriter$CompactRows.class";
		try (var in = WorkbenchPageResultWriter.class.getResourceAsStream(resource)) {
			var model = ClassFile.of().parse(in.readAllBytes());
			var calls = new ArrayList<String>();
			model.methods()
					.stream()
					.filter(m -> m.methodName().stringValue().equals("add"))
					.forEach(m -> m.code().orElseThrow().forEach(e -> {
						if (e instanceof InvokeInstruction i
								&& i.owner().asInternalName().equals("tools/jackson/databind/ObjectMapper")
								&& i.name().stringValue().equals("writeValue"))
							calls.add(i.name().stringValue());
					}));
			assertEquals(List.of(), calls,
					"compact protocol must use typed tokens rather than generic serializer dispatch");
		}
	}

